def transform(grid):
    h, w = len(grid), len(grid[0])
    n = None
    orient = None
    band_start = None

    # Find the full-width or full-height band of 3s.
    for r in range(h):
        if all(v == 3 for v in grid[r]):
            a = r
            while a > 0 and all(v == 3 for v in grid[a - 1]):
                a -= 1
            b = r
            while b + 1 < h and all(v == 3 for v in grid[b + 1]):
                b += 1
            if b - a + 1 > (n or 0):
                n, orient, band_start = b - a + 1, "h", a

    for c in range(w):
        if all(grid[r][c] == 3 for r in range(h)):
            a = c
            while a > 0 and all(grid[r][a - 1] == 3 for r in range(h)):
                a -= 1
            b = c
            while b + 1 < w and all(grid[r][b + 1] == 3 for r in range(h)):
                b += 1
            if b - a + 1 > (n or 0):
                n, orient, band_start = b - a + 1, "v", a

    out = [row[:] for row in grid]
    if n is None:
        return out

    step = n + 1
    tiles = []
    for r0 in range(0, h - n + 1, step):
        for c0 in range(0, w - n + 1, step):
            if orient == "h" and band_start <= r0 < band_start + n:
                continue
            if orient == "v" and band_start <= c0 < band_start + n:
                continue
            tile = [row[c0:c0+n] for row in grid[r0:r0+n]]
            if any(v == 2 for row in tile for v in row):
                tiles.append((r0, c0, tile))

    if not tiles:
        return [[0 if v == 3 else v for v in row] for row in out]

    template = tiles[0][2]

    # Clear the 3 band.
    for r in range(h):
        for c in range(w):
            if out[r][c] == 3:
                out[r][c] = 0

    # Copy the repeated pattern into those band slots selected by the pattern.
    if orient == "h":
        macro_r = band_start // step
        if macro_r < n:
            for macro_c in range((w + step - 1) // step):
                if macro_c < n and template[macro_r][macro_c] == 2:
                    r0, c0 = band_start, macro_c * step
                    if r0 + n <= h and c0 + n <= w:
                        for dr in range(n):
                            for dc in range(n):
                                out[r0 + dr][c0 + dc] = template[dr][dc]
                        tiles.append((r0, c0, template))
    else:
        macro_c = band_start // step
        if macro_c < n:
            for macro_r in range((h + step - 1) // step):
                if macro_r < n and template[macro_r][macro_c] == 2:
                    r0, c0 = macro_r * step, band_start
                    if r0 + n <= h and c0 + n <= w:
                        for dr in range(n):
                            for dc in range(n):
                                out[r0 + dr][c0 + dc] = template[dr][dc]
                        tiles.append((r0, c0, template))

    # Mark the pattern cell corresponding to each tile's macro-grid position.
    seen = set()
    for r0, c0, _ in tiles:
        if (r0, c0) in seen:
            continue
        seen.add((r0, c0))
        mr, mc = r0 // step, c0 // step
        if mr < n and mc < n and out[r0 + mr][c0 + mc] == 2:
            out[r0 + mr][c0 + mc] = 8

    return out
